-/* A conversation row's mark has its visible centre --mark-mid below its marker's top, where the row's twig (the
-   marker's ::before) meets it. An icon is centred in its marker, on the row's centre. A run mark is --ring-size, the
-   area an icon draws in, centred on the label's x-height midline (0.5ex above its baseline, in the label's font): the
-   marker takes part in the row's baseline alignment with the mark's bottom on the baseline, and the mark moves up to
-   the midline (a translate, so the spinner keeps turning about its own centre). */
-.conversation-row > .nav-marker {
-	--mark-mid: calc(var(--nav-icon) / 2);
+/* A conversation row's mark (an icon or a run mark) is centred on its label's cap-height midline, as text icons are.
+   The marker is baseline-aligned with the mark's bottom on the baseline, and a translate lifts the mark by
+   --mark-rise, so a spinner still turns about its own centre. --mark-mid is the mark's centre below the marker's top,
+   where the twig meets it. */
+.conversation-row {
+	--mark-rise: 0.5cap;
 }
-.conversation-row > .nav-marker:has(> .run-mark) {
-	--mark-mid: calc(var(--ring-size) - 0.5ex);
+@supports not (block-size: 1cap) {
+	.conversation-row {
+		--mark-rise: 0.5ex;
+	}
+}
+.conversation-row > .nav-marker {
+	--mark-size: var(--nav-icon);
+	--mark-mid: calc(var(--mark-size) - var(--mark-rise));
 	align-self: baseline;
 	align-items: baseline;
+	/* The mark takes no space above the baseline, so the label alone sets the row's height. */
+	margin-block-start: calc(-1 * var(--nav-icon));
+}
+.conversation-row > .nav-marker:has(> .run-mark) {
+	--mark-size: var(--ring-size);
+}
+.conversation-row > .nav-marker > * {
+	translate: 0 calc(var(--mark-mid) - var(--mark-size) / 2);
 }
 .conversation-row > .nav-marker > .run-mark {
 	width: var(--ring-size);
 	height: var(--ring-size);
-	translate: 0 calc(var(--mark-mid) - var(--ring-size) / 2);
 }
